<?php require __DIR__ . '/_shared.php';
$stmt=$pdo->prepare("SELECT COUNT(*) clicks, COUNT(DISTINCT DATE(created_at)) active_days FROM affiliate_clicks WHERE affiliate_id=?");$stmt->execute([$affiliateId]);$stats=$stmt->fetch(PDO::FETCH_ASSOC)?:[];
$stmt=$pdo->prepare("SELECT status,COUNT(*) total FROM affiliate_referrals WHERE affiliate_id=? GROUP BY status");$stmt->execute([$affiliateId]);$byStatus=[];foreach($stmt as $r){$byStatus[$r['status']]=(int)$r['total'];}
$stmt=$pdo->prepare("SELECT c.created_at,c.product_id,p.name product_name FROM affiliate_clicks c LEFT JOIN products p ON p.id=c.product_id WHERE c.affiliate_id=? ORDER BY c.created_at DESC LIMIT 50");$stmt->execute([$affiliateId]);$clicks=$stmt->fetchAll(PDO::FETCH_ASSOC);
aff_head('Clicks & Referrals','clicks'); ?>
<section class="mb-6"><p class="text-xs font-extrabold uppercase tracking-[.16em] text-sky-600">Performance tracking</p><h1 class="mt-2 text-3xl font-black tracking-tight text-slate-950">Clicks & referrals</h1><p class="mt-2 max-w-2xl text-slate-500">See how your links are performing and how visitors move into registered and qualified referrals.</p></section>
<section class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">Clicks</p><b class="mt-2 block text-3xl"><?=number_format((int)($stats['clicks']??0))?></b></div><div class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">Active days</p><b class="mt-2 block text-3xl"><?=number_format((int)($stats['active_days']??0))?></b></div><div class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">Registered</p><b class="mt-2 block text-3xl"><?=number_format($byStatus['registered']??0)?></b></div><div class="rounded-2xl border bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">Qualified</p><b class="mt-2 block text-3xl text-emerald-600"><?=number_format($byStatus['qualified']??0)?></b></div></section>
<section class="mt-6 grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><div class="rounded-2xl border bg-white p-6 shadow-sm"><h2 class="font-extrabold">Referral funnel</h2><?php foreach(['registered','verified','qualified','rejected'] as $s): ?><div class="mt-5"><div class="flex justify-between text-sm"><span><?=e(aff_label($s))?></span><b><?=number_format($byStatus[$s]??0)?></b></div><div class="mt-2 h-2 rounded-full bg-slate-100"><div class="h-2 rounded-full bg-sky-500" style="width:<?=min(100,(int)($byStatus[$s]??0)*100/max(1,(int)($stats['clicks']??0)))?>%"></div></div></div><?php endforeach; ?></div>
<div class="overflow-hidden rounded-2xl border bg-white shadow-sm"><div class="border-b p-5"><h2 class="font-extrabold">Recent clicks</h2></div><div class="divide-y"><?php if(!$clicks): ?><div class="p-10 text-center text-sm text-slate-500">No clicks have been recorded yet.</div><?php else: foreach($clicks as $c): ?><div class="flex items-center justify-between gap-4 p-4"><div><p class="text-sm font-bold"><?=e((string)($c['product_name']?:'Main referral link'))?></p><p class="mt-1 text-xs text-slate-500"><?=e(date('d M Y, H:i',strtotime((string)$c['created_at'])))?></p></div><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold text-slate-600"><?= $c['product_id']?'Product':'General' ?></span></div><?php endforeach; endif; ?></div></div></section><?php aff_foot();
